DataTableScript:
$ErrorActionPreference = 'Stop'
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot 'net10.0'
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'profile-cases.json'
$env:OFFICEIMO_BENCHMARK_DATA = Join-Path $PSScriptRoot 'fixtures'
$env:OFFICEIMO_COMPARISON_MASK = '65535'
$env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
$env:OFFICEIMO_PERFORMANCE_AA = '0'
$runner = Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-broad/compare/bin/Release/net10.0/Compare.dll'
foreach ($key in @( (Get-Content -LiteralPath $env:OFFICEIMO_COMPARISON_CASES -Raw | ConvertFrom-Json -AsHashtable).Keys | Sort-Object )) {
    $trace = Join-Path $PSScriptRoot "$key.nettrace"
    if (Test-Path -LiteralPath $trace) { throw "Profile already exists: $trace" }
    dotnet-trace collect --providers 'Microsoft-Windows-DotNETRuntime:0x1:5,Microsoft-DotNETCore-SampleProfiler' --output $trace -- dotnet $runner --profile $key candidate 100 *> (Join-Path $PSScriptRoot "$key-profile.log")
    if ($LASTEXITCODE) { throw "Profile collection failed: $key" }
    foreach ($scope in @(
        @{Name='complete';Root='ExcelNumericXmlReadBenchmarks.ReadCore'},
        @{Name='rows';Root='TryFillDataTableRowsXmlFast'}
    )) {
        $env:OFFICEIMO_TRACE_ROOT = $scope.Root
        $summaryPath = Join-Path $PSScriptRoot "$key-$($scope.Name)-summary.json"
        dotnet $runner --analyze $trace > $summaryPath
        if ($LASTEXITCODE) { throw "Profile analysis failed: $key / $($scope.Name)" }
        $summary = Get-Content -LiteralPath $summaryPath -Raw | ConvertFrom-Json
        [pscustomobject]@{Case=$key;Scope=$scope.Name;AllocationSamples=$summary.AllocationSamples;SampledAllocationBytes=$summary.SampledAllocationBytes;CpuSamples=$summary.CpuSamples;Types=$summary.Types | Select-Object -First 5;Owners=$summary.FirstOfficeFrame | Select-Object -First 5} | ConvertTo-Json -Depth 5 -Compress
    }
}
